local function v57(p4)
	local Character = LocalPlayer.Character
	local HumanoidRootPart

	if Character then
		HumanoidRootPart = Character:FindFirstChild("HumanoidRootPart")
	else
		HumanoidRootPart = Character
	end

	if HumanoidRootPart then
		local Position = HumanoidRootPart.Position

		for _, v in ipairs(CollectionService:GetTagged("Mob")) do
			local PrimaryPart = v.PrimaryPart

			if PrimaryPart then
				PrimaryPart = PrimaryPart.Position
			end

			if not PrimaryPart and v:IsA("Model") then
				PrimaryPart = v:GetPivot().Position
			end

			if PrimaryPart and (v.Parent and ((v:GetAttribute("Health") or 0) > 0 and (not v:GetAttribute("_Dying") and Vector3.new(PrimaryPart.X - Position.X, 0, PrimaryPart.Z - Position.Z).Magnitude <= p4))) then
				return true
			end
		end

		for _, v in ipairs(CollectionService:GetTagged("Combatant")) do
			if v:IsA("Humanoid") and v.Health > 0 then
				local Parent = v.Parent

				if Parent and (Parent ~= Character and not Players:GetPlayerFromCharacter(Parent)) then
					local HumanoidRootPart2 = Parent:FindFirstChild("HumanoidRootPart") or Parent.PrimaryPart

					if HumanoidRootPart2 then
						local Position2 = HumanoidRootPart2.Position

						if Vector3.new(Position2.X - Position.X, 0, Position2.Z - Position.Z).Magnitude <= p4 then
							return true
						end
					end
				end
			end
		end

		return false
	else
		return false
	end
end

